import * as React from 'react'
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import Stack from '@mui/material/Stack';
import { styled } from '@mui/material/styles';
import Paper from '@mui/material/Paper';
import Formulario from '../../componentes/herramientas/formulario';
import { genera_formulario, Form_todos, Ver_Valores, conexiones } from '../../constantes';
import Dialogo from '../../componentes/herramientas/dialogo';
import GenerarReporte from './generapdf';
const conversion = 2.83464567;
const conversion1 = 0.35277778;

const Item = styled(Paper)(({ theme }) => ({
    backgroundColor: '#fff',
    ...theme.typography.body2,
    padding: theme.spacing(1),
    textAlign: 'center',
    color: theme.palette.text.secondary,
    flexGrow: 1,
    
      backgroundColor: '#1A2027',
    
  }));

  
export default function CrearReporte(props) {
    const [state,setState] = React.useState({
        alto:279.4, ancho:215.9,
        componentes:[
            
        ]
    });
    let componentes=[];
    const [formulario,setFormulario] = React.useState(null);
    const [dialogo, setDialogo] = React.useState({open:false});
    
    let columnas=[];
    let filas = [];
    let conteo = 4.7;
    for (var i=1;i<((state.alto-9.4)/5)-12; i+=1){
        filas=[...filas,conteo];
        conteo+=5;
        // if (conteo===10) conteo=0;
    }
    conteo=2.95;

    for (var j=0;j<((state.ancho-10)/5)-10; j+=1){
        columnas=[...columnas,conteo];
        conteo+=5;
        // if (conteo>=col.length) conteo=0;
    }
    const Cambio = (nuevo) =>{
        setState({...state, ...nuevo})
    }

    const Agregar = async(valores) =>{
        console.log(valores)
        let lista = [...valores.componentes];
        console.log(lista);
        const pos = lista.findIndex(f=> f.field===valores.field);
        if(pos!==-1){
            lista[pos]={...valores}
        }else{
            lista =[...lista, 
                {
                    key:lista.length,
                    ...valores
                }
            ];
        }
        Cambio({componentes:lista});
        componentes=[...lista];
        setDialogo({open:false})
        Inicio(lista)
    }

    const Eliminar = async(valores)=>{
        console.log('Eliminar...', valores);
        const nuevos = await conexiones.Eliminar(valores,['sistemachs_reporte']);
        console.log(nuevos)
        Inicio();

    }
    const Guardar = async(valores)=>{
        const listado = {...valores, ...state};
        let componentes = [];
        listado.componentes.map(val=>{
            let campos={};
            Object.keys(val).map(val1=>{
                if(val1.indexOf('Error-')===-1 && val1.indexOf('componentes')===-1){
                    campos[val1]=val[val1];
                }
                return val1
            });
            componentes=[...componentes, campos];
            
        })
        console.log(listado, componentes);
        let nuevos ={
            _id:listado._id,
            nombre:listado.nombre,
            alto:Number(listado.alto),
            ancho:Number(listado.ancho),
            componentes
        }; 
        console.log(nuevos)
        // Object.keys(listado).map(f=>{ 
        //     if(f.indexOf('Error-')===-1){
        //         nuevos[f]= listado[f];
        //     }
        //     return f
        // });
        const respuesta = await conexiones.Guardar({_id:nuevos._id, valores:nuevos, multiples_valores:true},'sistemachs_reporte');
        Inicio(componentes);
    }

    const Modificar = async(valores, componentes) =>{
        let {config}=Ver_Valores();
        let nuevos = await genera_formulario({
            valores:{
                ...valores ===undefined ? {
                    fila:10, columna:10,
                    letra:10, lineas:5, linea:15
                } : valores,
                componentes
            }, campos: Form_todos('Form_reporte_crear_n') });
        nuevos.botones=[
            {
                name:'agregar', label:'Agregar elemento', title:'Agregar un elemento a reporte',
                variant:"contained", color:"success", validar:true, 
                onClick: Agregar,  icono:'add',
                sx:{...config.Estilos.Botones ? config.Estilos.Botones.Aceptar : {}},
            }
        ]
        setDialogo(
            {
                open:true,
                tam:'xs',
                Titulo: 'Nuevo Item',
                Cuerpo:
                  <div style={{margin:5, }}>
                    <Formulario {...nuevos}/>
                  </div>,
                Cerrar: () =>setDialogo({open:false})
            }
        )
    }
    const VerReporte = async(valores)=>{
        let {config}=Ver_Valores();
        console.log(valores);
        setDialogo(
            {
                open:true,
                Titulo: `Reporte ${valores.nombre}`,
                Cuerpo:
                  <div style={{margin:5, }}>
                    <GenerarReporte {...valores}/>
                  </div>,
                Cerrar: () =>setDialogo({open:false})
            }
        )

    }

    const Inicio=async(lista, otros=undefined)=>{
        let {config}=Ver_Valores();
        const valores ={
            ...otros ? otros : state,
            componentes:[...lista ? lista : state.componentes]
        };
        console.log(valores)
        let nuevos = await genera_formulario({
            valores, campos: Form_todos('Form_reporte_crear') });
        
        nuevos.titulos.recibos.onChange=(value)=>{
            console.log(state, value.resultados[value.name])
            Cambio(value.resultados[value.name]);
            Inicio(value.resultados[value.name].componentes,
                {
                    _id:value.resultados[value.name]._id,
                    nombre:value.resultados[value.name].nombre,
                    alto:value.resultados[value.name].alto,
                    ancho:value.resultados[value.name].ancho,
                }
            );

        }
        nuevos.titulos.alto.onChange=(value)=>{
            Cambio({[value.name]:Number(value.resultados[value.name])});

        }
        nuevos.titulos.ancho.onChange=(value)=>{
            
            Cambio({[value.name]:Number(value.resultados[value.name])});
        }
        nuevos.titulos.nombre.onChange=(value)=>{
            Cambio({[value.name]:value.resultados[value.name]});
        }
        nuevos.botones=[
            {
                name:'agregar', label:'Agregar elemento', title:'Agregar un elemento a reporte',
                variant:"contained", color:"success", 
                onClick: ()=>Modificar(undefined, lista ? lista : state.componentes),  icono:'add',
                sx:{...config.Estilos.Botones ? config.Estilos.Botones.Aceptar : {}},
            },
            {
                name:'reporte', label:'Ver Reporte', title:'Ver Reporte',
                variant:"contained", color:"success", 
                onClick: ()=>VerReporte(valores),  icono:'find_in_page',
                sx:{...config.Estilos.Botones ? config.Estilos.Botones.Aceptar : {}},
            },
            {
                name:'guardar', label:'Guardar', title:'Guardar',
                variant:"contained", color:"success", validar:true, 
                onClick: Guardar,  icono:'check',
                sx:{...config.Estilos.Botones ? config.Estilos.Botones.Aceptar : {}},
            },
            {
                name:'eliminar', label:'Eliminar', title:'Eliminar ',
                variant:"contained", color:"secondary", icono:"delete",
                sx:{...config.Estilos.Botones ? config.Estilos.Botones.Eliminar : {}},
                confirmar:'true', confirmar_mensaje:'Desea eliminar',confirmar_campo:'nombre',
                onClick: Eliminar,
            }
        ]
        setFormulario(nuevos);
        Cambio({...valores});//componentes:lista ? lista : state.componentes
    }

    React.useEffect(()=>{
        
        Inicio();
        return ()=>{
            delete Inicio()
        }
    },[])
    
    return (
        <Box sx={{backgroundColor:"#abb2b9 "}}>
            <Stack
                spacing={2 }
                direction='row'
            >
                <Item>
                    {formulario
                        ?   <Formulario {...formulario}/>
                        :   null
                    }
                </Item>
                <Item>
                    <Box sx={{  bgcolor:'#fff', 
                                width:state.ancho*conversion, height:state.alto*conversion, 
                                position:'relative'
                            }}
                        onClick={(event)=>{
                            console.log(event.clientY, event.clientX);

                        }}
                        onDragOver={(valor)=>{
                            // console.log('Entro..',valor);
                        }}
                       
                        onDrop={(valor)=>{
                            // console.log('Dentro..',valor);
                        }}
                        
                    >
                        
                        {filas.map(f=>
                            columnas.map(c=>
                                <div key={`${f}${c}`} style={{fontSize:8, position:'absolute', top:`${f}mm`, left:`${c}mm`, backgroundColor:'#000', height:'1mm', width:'1mm'}}
                                    onClick={()=>console.log('fila',f, 'columna', c)}
                                />
                                    
                                
                            )
                        )}
                        
                        {state.componentes.map((val,index)=>
                            <div key={val.key} 
                                style={{
                                    position:'absolute', 
                                    top:`${val.fila}px`, left:`${val.columna}px`,
                                    // backgroundColor:'#f0f'
                                }}
                                draggable={true}
                                onDoubleClick={()=>Modificar(val, state.componentes)}
                                onDragStart={(valor)=>{
                                    // console.log('Comienza>>>',valor.clientY, valor.clientX)
                                }}
                                onDragEnd={(valor)=>{
                                    // console.log('Fin>>>',valor)
                                    let componente = state.componentes;
                                    componente[index]={
                                        ...componente[index],
                                        fila:valor.clientY-100 , columna:valor.pageX - 575
                                    }
                                    Cambio({componentes:componente});
                                    Inicio(componente)
                                }} 
                                // onMouseMove={(event)=>{
                                //     console.log('>>>',event.pageX, event.pageY)
                                // }}
                            >
                                {val.tipo && val.tipo.titulo==='Texto'
                                    ?   <Typography 
                                            style={{
                                                fontSize:Number(val.letra), 
                                                textAlign:val.alinear ? val.alinear : 'left',
                                                width:val.ancho ? Number(val.ancho) : 'auto',
                                                backgroundColor: val.ancho ? '#d0dcd0' : ''
                                            }}
                                        > {val.field} </Typography>
                                    :   val.tipo && val.tipo.titulo==='Tabla'
                                    ?   Array.from({ length: Number(val.lineas) }, (_, index) => index + 1).map((i, j)=>
                                        <Typography key={val.key + i} 
                                            style={{position:'absolute', 
                                                top: `${j * Number(val.linea)}px`, 
                                                fontSize:Number(val.letra),
                                                textAlign:val.alinear ? val.alinear : 'left',
                                                width:val.ancho ? Number(val.ancho) : 'auto',
                                                backgroundColor: val.ancho ? '#d0dcd0' : ''
                                            }}
                                        > 
                                            {val.field+ ' '+ i} 
                                        </Typography>
                                    ): null
                                }
                                
                            </div>
                        )}
                    </Box>
                </Item>
            </Stack>
            <Dialogo {...dialogo} config={Ver_Valores().config}/>
        </Box>
    );
}