import React, {useRef} from 'react';
import jsPDF from 'jspdf'
import Typography from '@mui/material/Typography';
// import PropTypes from 'prop-types';
import Box from '@mui/material/Box';
// import EsperaReporte from '../../componentes/herramientas/pantallas/esperareporte';
import { Ver_Valores, conexiones, nuevo_Valores, Moneda } from '../../constantes';
import moment from 'moment';
// import Formulario from '../../componentes/herramientas/formulario';

const conversion = 2.83464567;
const conversion1 = 0.35277778;

export default function GenerarReportepdf(props) {
    const [state,setState] = React.useState({...props});
    const [pdf,setPdf]= React.useState();
    const [formula,setFormula] = React.useState();
    // let datos = Ver_Valores().datos_reporte;
    const reportTemplateRef = useRef(null);
    
    
    let columnas=[];
    let filas = [];
    let conteo = 4.7;
    for (var i=1;i<((state.alto-9.4)/5)-12; i+=1){
        filas=[...filas,conteo];
        conteo+=5;
        // if (conteo===10) conteo=0;
    }
    conteo=2.95;

    for (var j=0;j<((state.ancho-10)/5)-10; j+=1){
        columnas=[...columnas,conteo];
        conteo+=5;
        // if (conteo>=col.length) conteo=0;
    }
    
    const generarPdf=()=>{
        const doc = new jsPDF("p", "pt", "letter");

		doc.html(reportTemplateRef.current, {
			async callback(doc) {
				// await doc.save('document');
                
                // doc.autoPrint()
                setPdf(doc.output('bloburl'));
			},
		});
    }
    
    React.useEffect(()=>{
        const Inicio = async() =>{
            let {config}=Ver_Valores();
            
            let respuesta = await conexiones.Leer_C(['sistemachs_reporte'],{
                sistemachs_reporte:{'valores.nombre':props.reporte_nombre}
            });
            let componentes=[];
            if (respuesta.Respuesta==='Ok'){
                componentes = respuesta.datos.sistemachs_reporte.length===0 ? [] : {
                    ...respuesta.datos.sistemachs_reporte[respuesta.datos.sistemachs_reporte.length-1].valores
                }
            }
            
            
            let nuevos = {datos:{},titulos:{}}
            nuevos.botones=[
                {
                  name:'imprimir', label:'Generar Impresión', title:'Crea pdf para imprimir',
                  variant:"contained", color:"success", 
                  onClick: generarPdf, validar:'true', icono:'print',
                  sx:{...config.Estilos.Botones ? config.Estilos.Botones.Aceptar : {}},
                }
            ]
            setState({...props, ...componentes});
            setFormula(nuevos);
            
        }
        if (formula===undefined){
            Inicio();
        }
        // setTimeout(()=>{
            // generarPdf();
        // },1000)
        
    })
    React.useEffect(()=>{
        if (formula){
            
            nuevo_Valores({datos_reporte:formula.datos});
            // setTimeout(() => {
            //     generarPdf();
            // }, 1000);
        }
    },[formula]);
    const ejemplo = (datos,condicion,Moneda)=>{ 
        const {valores}= datos;
        const subtotal = valores 
                     && condicion
                     && condicion.moneda._id===1 
                     ?  Number(valores.formapago.totales.subtotal).toFixed(2)
                     :  valores 
                     ?  Number(valores.formapago.totales.subtotal * Number(condicion.tasa)).toFixed(2)
                     :'0,00';
        const desc = valores 
                    && valores.formapago.totales.desc 
                    && valores.formapago.totales.desc!==0 
                    && valores.formapago.totales.desc!=='0'
                    ? Number(subtotal * Number(valores.formapago.totales.desc) / 100).toFixed(2)
                    :'0.00';
        const total = (Number(subtotal) - Number(desc)).toFixed(2) ;
        const iva = valores 
                ? Number(Number(total * 16/100)).toFixed(2)
                :'0,00';
        const totalp = (Number(total) + Number(iva)).toFixed(2) ;
        return Moneda(total, condicion && condicion.moneda._id===1 ? '$' : 'Bs', false);
    }
    return (
        <div>
            <div style={{ alignContent:'center', alignItems:'center'}}>
                                
                
                        <Box sx={{  bgcolor:'#fff', 
                                    width:state.ancho*conversion, //height:state.alto*conversion, 
                                    //width:612, 
                                    height:700,
                                    position:'relative'
                                }}    
                        >
                            
                            {state.componentes ? state.componentes.map((val,index)=>{
                                let lista =[];
                                if (val.tipo && val.tipo.titulo==='Tabla'){
                                    lista = val.formato ? eval(val.formato)(state.datos, state.Condicion, Moneda) : [];
                                }
                                
                                return (
                                <div key={val.key} 
                                    style={{
                                        position:'absolute', 
                                        top:`${val.fila}px`, left:`${val.columna}px`,
                                        // backgroundColor:'#f0f'
                                    }}
                                    
                                >
                                    {val.tipo && val.tipo.titulo==='Texto'
                                        ?   <Typography 
                                                style={{
                                                    fontSize:Number(val.letra), 
                                                    textAlign:val.alinear ? val.alinear : 'left',
                                                    width:val.ancho ? Number(val.ancho) : 'auto',
                                                }}
                                            > {val.formato ? eval(val.formato)(state.datos, state.Condicion, Moneda) : val.field} </Typography>
                                        :   val.tipo && val.tipo.titulo==='Tabla'
                                        ?   lista.map((dato, j)=>
                                            <Typography key={dato._id + i} 
                                                style={{position:'absolute', 
                                                    top: `${j * Number(val.linea)}px`, 
                                                    fontSize:Number(val.letra),
                                                    textAlign:val.alinear ? val.alinear : 'left',
                                                    width:val.ancho ? Number(val.ancho) : 'auto',
                                                }}
                                                noWrap
                                            > 
                                                { dato[val.field]} 
                                            </Typography>
                                        ): null
                                    }
                                    
                                </div>
                                )
                            }) : null}
                        </Box>
                    
                
            </div>
               
        </div>
    );
}