//Funciones generales
const Actualizar = (repetir=false) =>{
  const {Sincronizar} = Ver_Valores();
  setTimeout(() => {
    Sincronizar({esperando_local:false, repetir:true, verificar:repetir}); 
  }, 3000);
}
const Guardar_modificaciones = async(User, tabla, tipo, newdatos, actualizar)=>{
  const {api} = Ver_Valores();
  const codigo_navegador= await Codigo_navegador(api.valores.api);
  //Para indicar la modificasion 
  const table = Ver_Valores().valores.models[0];
  const Modificar = Database(table);
  const fecha = new Date();
  const _id_registro = `${tabla}-${tipo}-${String(newdatos._id)}`
  const anterior = await Modificar.findOne({'valores._id_registro':_id_registro})
  if (anterior===null){
    const _id = ObjectID(new Date().getTime()).toHexString();
    await Modificar.insert({
      _id, 
      valores:{
        _id_registro, 
        tipo, 
        tabla, 
        newdatos, 
        origen:codigo_navegador, 
        clientes:[codigo_navegador]
      }, actualizado:`${User.name}-${codigo_navegador}`,
      createdAt: fecha, updatedAt:fecha,
    })  
  }else{
    await Modificar.updateOne({'valores._id_registro':_id_registro},{
      ...anterior, valores:{
        ...anterior.valores,
        newdatos,
        origen:codigo_navegador,
        clientes:[codigo_navegador]
      },
      updatedAt:fecha,
    })
  }
  if (actualizar){
    Actualizar();
  }
}
const Guardar_data=async(User, tabla,newdatos, local=true, actualizar=true)=>{
    //agregado para ingresar sede
    const sede = Ver_Valores().sede;
    if (newdatos.valores.sede===null || newdatos.valores.sede===undefined){
      newdatos.valores.sede =  sede;
    }
    //----------------------------
    const fecha = new Date();
    let DB = Database(tabla);
    const _id = ObjectID(fecha.getTime()).toHexString();
    let tipo = 'Nuevo';
    if (newdatos._id){//(newdatos._id){
        const anterior = await DB.findOne({_id:newdatos._id});
        // const hash_chs = await Hash_chs({...newdatos});
        newdatos = {
            ...anterior,
            actualizado:User.username, 
            updatedAt:String(fecha),
            ...newdatos, 
             
            local
        }
        tipo='Modificar';
        await DB.update({_id:newdatos._id},{...newdatos},{ upsert: true });

    } else {
        let cod_chs = await Codigo_chs({...newdatos['multiples_valores'] ? newdatos.valores : newdatos});
        // const hash_chs = await Hash_chs({...newdatos, cod_chs})
        newdatos = {
            _id,
            actualizado:User.username, 
            createdAt: String(fecha), updatedAt:String(fecha),
            ...newdatos,
            cod_chs, 
             
            local
        }
        await DB.insert({...newdatos});
    }
    newdatos=newdatos._id ? newdatos : {...newdatos, _id};
    await Guardar_modificaciones(User, tabla, tipo, newdatos, actualizar);
    let resultado = await DB.find();    
    return resultado
}

