export const Ingreso_EgresoL = async (props)=>{
  let {datos} = props;
  
  let Ingreso;
  let Egreso;
  let Inventario;
  
  if (datos.tipo === undefined ){
      return({Respuesta:'Ok', inventario:[], mensaje:'Tipo de ingreso y egresos no conocidos'});
  }
  if (datos.tipo==='Materia Prima'){
      Ingreso=Database(tabla_ingresomp);//require(`../models/sistemachs_Ingresomp`);
      Egreso=Database(tabla_egresomp);//require(`../models/sistemachs_Egresomp`);
      Inventario = Database(tabla_inventariomp);//require(`../models/sistemachs_Inventariomp`);
  }else if (datos.tipo==='Empaque'){
      Ingreso= Database(tabla_ingresoem);//require(`../models/sistemachs_Ingresoem`);
      Egreso= Database(tabla_egresoem);//require(`../models/sistemachs_Egresoem`);
      Inventario = Database(tabla_empaque);//require(`../models/sistemachs_Empaque`);
  }else if (datos.tipo==='Producto Terminado'){
      Ingreso= Database(tabla_ingresopt);//require(`../models/sistemachs_Ingresopt`);
      Egreso= Database(tabla_egresopt);//require(`../models/sistemachs_Egresopt`);
      Inventario = Database(tabla_inventariopt);//require(`../models/sistemachs_Inventariopt`);
  }else{
      return({Respuesta:'Ok', inventario:[], mensaje:'Tipo de ingreso y egresos no conocidos'});
  }
  let ingresos=[];
  let egresos=[];
  let inventario = await Inventario.find();
  //agregado para filtrar por cede
  const sede = Ver_Valores().sede;
  inventario= inventario.filter(f=>(f.valores.sede===undefined && sede==='Coro') ||(f.valores.sede===sede) )
  //------------------------------
  inventario= inventario.map(val=>{return{_id:val._id, ...val.valores, cantidadA:0}});
  if (datos.meses==='Todos'){
      let ingreso = await Ingreso.find();
      ingresos = ingreso.map(val=>{return{_id: val._id, actualizado: val.actualizado, ...val.valores}});
      let egreso = await Egreso.find();
      egresos = egreso.map(val=>{return{_id: val._id, actualizado: val.actualizado, ...val.valores}});
  }else{
      for (var i=0; i<datos.meses.length;i++){
          const mes = datos.meses[i];
          let ingreso = await Ingreso.find({'valores.fecha':mes})//({$text: {$search: mes, $caseSensitive: false}});
          // ingreso= ingreso.filter(f=>f.valores.fecha===mes).map(val=>{return{_id: val._id, actualizado: val.actualizado, ...val.valores}});
          ingreso= ingreso.filter(f=>(f.valores.sede===undefined && sede==='Coro') ||(f.valores.sede===sede) );
          ingreso= ingreso.map(val=>{return{_id: val._id, actualizado: val.actualizado, ...val.valores}});
          ingresos=[...ingresos,...ingreso];
          let egreso = await Egreso.find({'valores.fecha':mes})//({$text: {$search: mes, $caseSensitive: false}});
          // egreso= egreso.filter(f=>f.valores.fecha===mes).map(val=>{return{_id: val._id, actualizado: val.actualizado, ...val.valores}});
          egreso = egreso.filter(f=>(f.valores.sede===undefined && sede==='Coro') ||(f.valores.sede===sede) );
          egreso= egreso.map(val=>{return{_id: val._id, actualizado: val.actualizado, ...val.valores}});
          egresos=[...egresos,...egreso];
      }
  }
  for (var i1=0; i1<ingresos.length; i1++){
      const ingreso = ingresos[i1];
      
      for (var j=0; j<ingreso.movimiento.length;j++){
          const mp= ingreso.movimiento[j];
          
          const pos = inventario.findIndex(f=>String(f._id)===String(mp._id));
          
          if (pos!==-1){
              if(inventario[pos][ingreso.fecha]){
                  inventario[pos][ingreso.fecha].ingreso+=Number(mp.cantidad);  
              }else{
                  inventario[pos][ingreso.fecha]={ingreso:Number(mp.cantidad), egreso:0};
              }
              inventario[pos].cantidadA+=Number(mp.cantidad);

          }
      }
  }
  
  for (var i2=0; i2<egresos.length; i2++){
      const egreso = egresos[i2];
      
      for (var j1=0; j1<egreso.movimiento.length;j1++){
          const mp= egreso.movimiento[j1];
          const pos = inventario.findIndex(f=>String(f._id)===String(mp._id) || f.codigo===mp.codigo);
          if (pos!==-1){
              if(inventario[pos][egreso.fecha]){
                  inventario[pos][egreso.fecha].egreso+=Number(mp.cantidad);  
              }else{
                  inventario[pos][egreso.fecha]={ingreso:0, egreso:Number(mp.cantidad)};
              }
              inventario[pos].cantidadA-=Number(mp.cantidad);
          }
      }
  }
  
  inventario = inventario.sort((a,b)=> a.categoria && b.categoria && (a.categoria.titulo>b.categoria.titulo) ? 1 : -1);
  
  return({Respuesta:'Ok', inventario, ingresos, egresos});
}

