import React, {Component} from 'react';
// import MailIcon from '@material-ui/icons/Mail';
// import NotificationsIcon from '@material-ui/icons/Notifications';
import Stack from '@mui/material/Stack';
import { Icon, Box, Divider, IconButton } from '@mui/material';
import Cuerpo from '../../componentes/herramientas/cuerpo';
import TablaMultiple from '../../componentes/herramientas/tabla/tabla_multiple';
import { Form_todos, Titulos_todos, MaysPrimera, Ver_Valores, genera_formulario, conexiones } from '../../constantes';
import Reporte from '../../componentes/reporte';
import Cargando from '../../componentes/esperar/cargar';
import Formulapdf from './pdf/formulapdf';
import Dialogo from '../../componentes/herramientas/dialogo';
import Formulario from '../../componentes/herramientas/formulario';
import CancelIcon from '@mui/icons-material/Cancel';

export default class Registros extends Component {
  constructor(props) {
      super(props);

      this.state = {
          cargando:true,
          props: this.props,
          Config:this.props.Config,
          Inicio:this.Inicio,
          dialogo:{open:false}
      }
  }

  Condiciones = async(campo, datos) =>{
    let {valores}= datos
    switch (campo) {
      case 'User_api':{
        if (datos.password!==''){
          // datos.password =await encriptado.Hash_password(datos.npassword)
          datos.newpassword=datos.password;
          
        }
        // else{
          delete datos.password
        // }
        datos.categoria = typeof datos.categoria === 'object' ? datos.categoria._id : datos.categoria 
        return datos
      }
      
      default:
        return valores;
    }

  }
  Imprimir_formula = (dato)=>{
    return{
      tipo:'Dialogo',
      dialogo:{
        open:true,
        tam:'xl',
        Titulo:dato.mezcla,
        Cuerpo:<Reporte datos={dato} reporte={Formulapdf} sizePagina= {{width:612, height:396}}/>,
      }
    }
  }
  Define_tabla = (tabla, sede) =>{
    if (sede && sede!=='Coro'){
      sede = sede.replace(' ','_');
      const pos = tabla.indexOf('_');
      tabla = tabla.slice(0,pos)+'_'+sede+tabla.slice(pos);
    }
    return tabla
  }
  Copiar = async(valores)=>{
    this.setState({cargando:true});
    const {origen, sede, tabla} = valores;
    const destino = sede.titulo;
    const tablao= this.Define_tabla(tabla, origen);
    const tablad= this.Define_tabla(tabla, destino);
    console.log(tablao, tablad);
    
    const respuesta = await conexiones.Copiar(tablao, tablad, undefined);
    console.log(respuesta);
    if (respuesta.Respuesta==='Ok'){
      this.setState({cargando:false, dialogo:{open:false}});
    }
    return respuesta

  }
  Copiado = async(campo)=>{
    const {Config} = this.state;
    let nuevos = await genera_formulario({valores:{tabla:campo, origen:Ver_Valores().sede}, campos: Form_todos('Form_Sedes') })
    const lista = Ver_Valores().config.Listas[nuevos.titulos.sede.lista].filter(f=>f.titulo!==Ver_Valores().sede );
    nuevos.titulos.sede.lista= lista;

    nuevos.botones=[
      {
        name:'copiar', label:'Copiar', title:'Copiar ',
        variant:"contained", color:"success", icono:<Icon>folder_copy</Icon>,
        onClick: this.Copiar, validar:'true', 
        sx:{...Config.Estilos.Botones ? Config.Estilos.Botones.Aceptar : {}},
        
      },
      {
        name:'cancelar', label:'Cancelar', title:'Cancelar',
        variant:"contained",  icono:<CancelIcon/>,
        sx:{...Config.Estilos.Botones ? Config.Estilos.Botones.Cancelar : {}},
        onClick: ()=>this.setState({dialogo:{open:false}})
      },
    ]
    this.setState({dialogo:{
      open:true,
      
      Titulo:'Desea copiar los de registro ',
      Cuerpo:<Formulario {...nuevos}/>,
      Cerrar: ()=>{
          this.setState({dialogo:{open:false}});
          
      },
    }})
  }
  Editores = async(campo)=>{
    
    let multiples_valores= true;//campo.indexOf('User_api')===-1
    let nuevo_campo = campo.indexOf('User_api')!==-1 ? 'User_api' : campo.indexOf('Lista_Venta')!==-1 ? 'Lista_Venta' : campo.split('_')[1];//MaysPrimera(campo.replace('colegio_',''))
    let Titulo_dialogo={
      sistemachs_Proveedor:(dato)=>`${dato.rif} ${dato.nombre}`,
      sistemachs_Cliente: (dato)=>`${dato.rif} ${dato.nombre}`,
      sistemachs_Empaque: (dato)=>dato.codigo,
      sistemachs_Inventariomp: (dato)=>dato.codigo,
      sistemachs_Formula: (dato, proceso)=>{
        const imprimir = this.Imprimir_formula(dato);
        return <Stack direction="row" spacing={2} divider={<Divider orientation="vertical" flexItem />}>
          <Box>{dato.mezcla}</Box>
          <Box><IconButton onClick={()=>proceso(imprimir)}><Icon>print</Icon></IconButton></Box>
        </Stack>
      },
      sistemachs_Inventariopt:(dato)=>dato.codigo,
      sistemachs_User_api:(dato)=>dato.username,
    }
    let Eliminar={
      Proveedor:'nombre',
      Cliente: 'nombre',
      Empaque:'codigo',
      Inventariomp:'codigo',
      Formula:'mezcla',
      Inventariopt:'codigo',
      User_api: 'username'
    }
    const ordenar={
      Empaque:(valores)=>{
        const nuevo = valores.sort((a,b)=> Number(a.valores.orden) > Number(b.valores.orden) ? 1 : -1);    
        return nuevo
      },
      Inventariomp:(valores)=>{
        const nuevo = valores.sort((a,b)=> Number(a.valores.orden) > Number(b.valores.orden) ? 1 : -1);    
        return nuevo
      },
      Inventariopt:(valores)=>{
        const nuevo = valores.sort((a,b)=> Number(a.valores.orden) > Number(b.valores.orden) ? 1 : -1);    
        return nuevo
      }
    }
    let Titulo;
    
    switch(campo){
      case 'sistemachs_Cliente':{
        Titulo= 'CLIENTES'
        break;
      }
      case 'sistemachs_Proveedor':{
        Titulo= 'PROVEEDORES'
        break;
      }
      case 'sistemachs_Empaque':{
        Titulo= 'EMPAQUES'
        break;
      }
      case 'sistemachs_Formula':{
        Titulo= 'FORMULAS'
        break;
      }
      case 'sistemachs_Inventariomp':{
        Titulo= 'MATERIAS PRIMAS'
        break;
      }
      case 'sistemachs_Inventariopt':{
        Titulo= 'PRODUCTO TERMINADO'
        break;
      }
      case 'sistemachs_Lista_Venta':{
        Titulo= 'LISTAS DE PRECIO DE VENTA'
        break;
      }
      case 'sistemachs_User_api':{
        Titulo= 'USUARIOS'
        break;
      }
      case 'sistemachs_Agencia':{
        Titulo= 'AGENCIAS'
        break;
      }
      case 'sistemachs_Modificacion':{
        Titulo= 'ACTUALIZACIONES'
        break;
      }
      default:{
        Titulo=campo;
      }
    }

    const funcion= Titulo_dialogo[campo];
    const {tipo}= Ver_Valores();
    const Titulos_tabla = await Titulos_todos(`Titulos_${nuevo_campo}`)
    return <div>
              <TablaMultiple
                {...this.state.props}
                Alto={tipo==='Web' ? window.innerHeight * 0.65: window.innerHeight * 0.8 }
                multiples_valores={multiples_valores}
                Agregar_mas={false}//multiples_valores}
                Condiciones={this.Condiciones}
                Columnas={2} 
                Form_origen = {Form_todos(`Form_${nuevo_campo}`)}
                Titulo_tabla={Titulo}
                Table = {campo}
                cargaporparte={{condicion:{}}}
                Eliminar_props={(dato)=>{
                    return `Desea eliminar de ${nuevo_campo} ${dato._id}`
                }}
                ordenar={(valores)=>{
                  if (ordenar[nuevo_campo]){
                    return ordenar[nuevo_campo](valores);
                  }
                  
                  return valores
                }}
                Accionesmas={
                  <IconButton  title={'Copiar los Registro a otra Sede'} onClick={()=>this.Copiado(campo)}>
                    <Icon style={{color:'#fff'}}>folder_copy</Icon>
                  </IconButton>
                }
                sinpaginacion={ordenar[nuevo_campo]}
                Eliminar= {Eliminar[nuevo_campo] ? Eliminar[nuevo_campo] : '_id'}
                Titulo_dialogo ={(dato, proceso)=> dato._id ?  Titulo_dialogo[campo] ? funcion(dato, proceso) : `Registro ${dato._id}`: `Nuevo registro en ${Titulo}`}
                Titulos_tabla = {Titulos_tabla}
            />
          </div>
  }
  
  Inicio = async() =>{
    const {User} = Ver_Valores();
    
    // let database= await conexiones.DataBase();
    let Bloques1={PROVEEDORES:null, CLIENTES:null, 'MATERIAS PRIMAS':null, EMPAQUES:null, FORMULAS:null, 'PRODUCTO TERMINADO':null}
    let models=['sistemachs_Cliente','sistemachs_Proveedor',
                'sistemachs_Empaque', 'sistemachs_Formula',
                'sistemachs_Inventariomp','sistemachs_Inventariopt',
                'sistemachs_Lista_Venta',
                'sistemachs_User_api', 'sistemachs_Agencia', 
                ...Number(User.categoria)===0  || User.categoria._id===0 ? ['sistemachs_Modificacion'] : [],  
              ]
    //models.map(async(val,i)=>{
      for (var i = 0; i < models.length; i++){
      
        const val =  models[i];
        if ((val.indexOf('sistemachs_')!==-1 )  && ['Api'].indexOf(val)===-1 ){
            let nuevo = MaysPrimera(val)
            switch(val){
              case 'sistemachs_Cliente':{
                nuevo= 'CLIENTES'
                break;
              }
              case 'sistemachs_Proveedor':{
                nuevo= 'PROVEEDORES'
                break;
              }
              case 'sistemachs_Empaque':{
                nuevo= 'EMPAQUES'
                break;
              }
              case 'sistemachs_Formula':{
                nuevo= 'FORMULAS'
                break;
              }
              case 'sistemachs_Inventariomp':{
                nuevo= 'MATERIAS PRIMAS'
                break;
              }
              case 'sistemachs_Inventariopt':{
                nuevo= 'PRODUCTO TERMINADO'
                break;
              }
              case 'sistemachs_Lista_Venta':{
                nuevo= 'LISTAS PRECIO DE VENTA'
                break;
              }
              case 'sistemachs_User_api':{
                nuevo= 'USUARIOS'
                break;
              }
              case 'sistemachs_Agencia':{
                nuevo= 'AGENCIAS'
                break;
              }
              case 'sistemachs_Modificacion':{
                nuevo= 'ACTUALIZACIONES'
                break;
              }
              default:{

              }
            }

            Bloques1[nuevo]= await this.Editores(val);
        }
        // return {_id:i, titulo:val, value:val}
    }//)
   
    let Bloques={
     
      ...Bloques1
    }

    this.setState({Bloques, BloquesT:Bloques, cargando:false})
  }
  async componentDidMount(){
    this.Inicio();
    this.setState({sede:Ver_Valores().sede})
    
  }

  static getDerivedStateFromProps(props, state) {

    if (props !== state.props) {
      if (Ver_Valores().sede!==state.sede){
        setTimeout(() => {
          state.Inicio()  
        }, 500);
        
      }
      return {
        props,
        Config:props.Config,
        sede:Ver_Valores().sede,
        ...Ver_Valores().sede!==state.sede ? {Bloques:null, BloquesT:null,} : {},
        cargando : Ver_Valores().sede!==state.sede
      };
    }
    // No state update necessary
    return null;
  }

  render(){
    const {Bloques, cargando, dialogo}=this.state;
    return (
      <div style={{width:'100%', height:'100%',position: "relative"}}>
        <Cuerpo Bloques={Bloques}/>
        <Cargando open={cargando}/>
        <Dialogo {...dialogo} config={this.state.props.Config}/>
      </div>
    )
  }
}
