import React, {useRef} from 'react';
import Grid from '@mui/material/Grid2';
import jsPDF from 'jspdf'
import Typography from '@mui/material/Typography';
import LinearProgress from '@mui/material/LinearProgress';
// import PropTypes from 'prop-types';
import Box from '@mui/material/Box';
// import EsperaReporte from '../../componentes/herramientas/pantallas/esperareporte';
import { Ver_Valores, nuevo_Valores } from '../../constantes';
// import Formulario from '../../componentes/herramientas/formulario';

const conversion = 2.83464567;
const conversion1 = 0.35277778;

export default function GenerarReporte(props) {
    const [state,setState] = React.useState({...props});
    const [pdf,setPdf]= React.useState();
    const [formula,setFormula] = React.useState();
    // let datos = Ver_Valores().datos_reporte;
    const reportTemplateRef = useRef(null);
    
    
    let columnas=[];
    let filas = [];
    let conteo = 4.7;
    for (var i=1;i<((state.alto-9.4)/5)-12; i+=1){
        filas=[...filas,conteo];
        conteo+=5;
        // if (conteo===10) conteo=0;
    }
    conteo=2.95;

    for (var j=0;j<((state.ancho-10)/5)-10; j+=1){
        columnas=[...columnas,conteo];
        conteo+=5;
        // if (conteo>=col.length) conteo=0;
    }
    
    const generarPdf=()=>{
        const doc = new jsPDF("p", "pt", "letter");

		doc.html(reportTemplateRef.current, {
			async callback(doc) {
				// await doc.save('document');
                
                // doc.autoPrint()
                setPdf(doc.output('bloburl'));
			},
		});
    }
    
    React.useEffect(()=>{
        const Inicio = async() =>{
            let {config}=Ver_Valores();
            
            let nuevos = {datos:{},titulos:{}}
            nuevos.botones=[
                {
                  name:'imprimir', label:'Generar Impresión', title:'Crea pdf para imprimir',
                  variant:"contained", color:"success", 
                  onClick: generarPdf, validar:'true', icono:'print',
                  sx:{...config.Estilos.Botones ? config.Estilos.Botones.Aceptar : {}},
                }
            ]
            setState({...props});
            setFormula(nuevos);
            
        }
        if (formula===undefined){
            Inicio();
        }
        // setTimeout(()=>{
            // generarPdf();
        // },1000)
        
    })
    React.useEffect(()=>{
        if (formula){
            
            nuevo_Valores({datos_reporte:formula.datos});
            setTimeout(() => {
                generarPdf();
            }, 1000);
        }
    },[formula]);

    return (
        <div>
            <Grid container spacing={0.5} justifyContent="center"
                    alignItems="center"
            >

                <Grid size={10} item style={{backgroundColor:'#DFDFE1', padding:10}}>
                    {pdf 
                        ?   <div style={{height:window.innerHeight * 0.8}}>
                                <embed src={`${pdf}#view=Fit=1&toolbar=1&navpanes=0&scrollbar=1`} type="application/pdf" width="100%" height={'100%' } />
                            </div>
                        :   <div style={{height:window.innerHeight * 0.8, alignContent:'center', alignItems:'center'}}>
                                <Box sx={{ width: '100%' }}>
                                    <LinearProgress color="inherit"/>
                                    <Typography variant="h6" sx={{textAlign:'center'}}>
                                        Generando PDF...
                                    </Typography>
                                </Box>
                                <div ref={reportTemplateRef}>
                                    <div >
                                        <Box sx={{  bgcolor:'#fff', 
                                                    width:state.ancho*conversion, height:state.alto*conversion, 
                                                    position:'relative'
                                                }}    
                                        >
                                            {filas.map(f=>
                                                columnas.map(c=>
                                                    <div key={`${f}${c}`} style={{fontSize:8, position:'absolute', top:`${f}mm`, left:`${c}mm`, backgroundColor:'#000', height:'1mm', width:'1mm'}}
                                                        onClick={()=>console.log('fila',f, 'columna', c)}
                                                    />
                                                        
                                                    
                                                )
                                            )}
                                            {state.componentes.map((val,index)=>
                                                <div key={val.key} 
                                                    style={{
                                                        position:'absolute', 
                                                        top:`${val.fila}px`, left:`${val.columna}px`,
                                                        // backgroundColor:'#f0f'
                                                    }}
                                                    
                                                >
                                                    {val.tipo && val.tipo.titulo==='Texto'
                                                        ?   <Typography 
                                                                style={{
                                                                    fontSize:Number(val.letra), 
                                                                    textAlign:val.alinear ? val.alinear : 'left',
                                                                    width:val.ancho ? Number(val.ancho) : 'auto',
                                                                }}
                                                            > {val.field} </Typography>
                                                        :   val.tipo && val.tipo.titulo==='Tabla'
                                                        ?   Array.from({ length: Number(val.lineas) }, (_, index) => index + 1).map((i, j)=>
                                                            <Typography key={val.key + i} 
                                                                style={{position:'absolute', 
                                                                    top: `${j * Number(val.linea)}px`, 
                                                                    fontSize:Number(val.letra),
                                                                    textAlign:val.alinear ? val.alinear : 'left',
                                                                    width:val.ancho ? Number(val.ancho) : 'auto',
                                                                }}
                                                            > 
                                                                {val.field} 
                                                            </Typography>
                                                        ): null
                                                    }
                                                    
                                                </div>
                                            )}
                                        </Box>
                                    </div>
                                </div>
                            </div>
                    }
                </Grid>
                
                
            </Grid>
        </div>
    );
}