import React, {Component} from 'react';
// import MailIcon from '@material-ui/icons/Mail';
// import NotificationsIcon from '@material-ui/icons/Notifications';
import Box from '@mui/material/Box';

import Stack from '@mui/material/Stack';

import {Titulos_todos ,conexiones, Form_todos, genera_formulario, Ver_Valores} from '../../../../constantes';
import Tabla from '../../../../componentes/herramientas/tabla';
// import Tabla from '../../../../componentes/herramientas/tablamostrar';
import Dialogo from '../../../../componentes/herramientas/dialogo';
import moment from 'moment';
import AddIcon from '@mui/icons-material/AddCircle';
import IconButton from '@mui/material/IconButton';
import AutorenewIcon from '@mui/icons-material/Autorenew';
import { confirmAlert } from 'react-confirm-alert'; // Import
import 'react-confirm-alert/src/react-confirm-alert.css';
import Venta from '../../venta';
import Reporte from '../pdf/reporte';
import Cargando from '../../../../componentes/esperar/cargar';
import Formulario from '../../../../componentes/herramientas/formulario';


export default class Traslado extends Component {
  constructor(props) {
      super(props);

      this.state = {
          cargando:true,
          props: this.props,
          Config:this.props.Config,
          datos:[],
          dialogo:{open:false},
          dialogo1:{open:false},
      }
  }

 
  Seleccionar_dia = (dian)=>(value) =>{
    let dia = this.state.dia;
    let diaf = this.state.diaf;
    if (dian==='dia') dia = value['$d'];
    else diaf= value['$d']; 
    this.setState({[dian]:value['$d']});
    this.Inicio(dia, diaf)
  }
  Refrescar = ()=>{
    let dia = this.state.dia;
    let diaf = this.state.diaf;
    this.Inicio(dia, diaf);
  }
  Inicio = async(dia, diaf)=>{
    console.log('>>>>>>>>>>por aqui ...')
    if (dia===undefined || dia===null){
      dia = new Date();
      dia.setDate(1);  
    }
    if (diaf===undefined || diaf===null){
      diaf = new Date();
      var ultimoDia = new Date(diaf.getFullYear(), diaf.getMonth() + 1, 0).getUTCDate();
      
      diaf.setDate(ultimoDia); 
    }
    this.setState({cargando:true});
    let forma = {...Form_todos('Form_fecha')};
    forma.columna= 2;
    let otro = {...forma.value[0], key:'fechaf', name:'fechaf', nombre:'fechaf'};
    forma.value=[...forma.value, otro];
    
    let nuevos = await genera_formulario({valores:{}, campos: forma });
    
    nuevos.titulos[0].value.fecha.value= dia;
    nuevos.titulos[0].value.fecha.label='Fecha Inicial';
    nuevos.titulos[0].value.fecha.onAccept = this.Seleccionar_dia('dia');
    nuevos.titulos[0].value.fechaf.value= diaf;
    nuevos.titulos[0].value.fechaf.label='Fecha Final';
    nuevos.titulos[0].value.fechaf.onAccept = this.Seleccionar_dia('diaf');
    let titulos = await Titulos_todos('Titulos_Ventas');
    titulos[1].formato=(dato)=>{
      const fecha = `${dato.valores ? moment(dato.valores.fecha).format('DD/MM/YYYY') : moment(dato.fecha).format('DD/MM/YYYY')}`;
      return fecha
    }
    let resp= await conexiones.Traslado({fecha:{dia:moment(dia).format('YYYY-MM-DD'),diaf:moment(diaf).format('YYYY-MM-DD')} });
    console.log('>>>>>>>>>>>>>>>>>>>>>>>>', resp)
    let datos=[];
    let facturado=0;
    let pendiente=0;
    let cancelado=0;
    let deproduccion=0;

    if (resp.Respuesta==='Ok'){
      datos= [...resp.traslados];
      facturado=resp.facturado;
      pendiente=resp.pendiente;
      cancelado=resp.total;
      deproduccion=resp.deproduccion;
    }
    
    
    this.setState({cargando:false, dia, diaf, fecha:nuevos, datos, titulos, facturado, deproduccion,pendiente, cancelado})  
    
    
  }
  async componentDidMount(){
    this.Inicio();
    this.state.props.socket.on(`Actualizar_traslado`, data => {
      this.Refrescar();     
    })
  }
  componentWillUnmount(){
    this.state.props.socket.off('Actualizar_traslado');
  }


  static getDerivedStateFromProps(props, state) {

    if (props !== state.props) {
        
      return {
        props,
        Config:props.Config,
      };
    }
    // No state update necessary
    return null;
  }
  
  Abrir = (data)=>{
    confirmAlert({
      title: 'Seleccione Opción ',
      
      buttons: [
        {
          label: 'Modificar',
          onClick: async () => {
            this.Modificar(data);
          }
        },
        {
          label: 'Imprimir',
          onClick: async () => {
            // setTimeout(()=>{
            //   this.Imprimir(data);
            // },200)
            this.Mostrar(data,'GUIA DE TRASLADO')
          }
        }
      ]
    });

  }
  Imprimir = (data) =>{
    confirmAlert({
      title: 'Que desea imprimir?',
      
      buttons: [
        {
          label: 'NOTA DE ENTREGA',
          onClick: async () => {
            this.Mostrar(data,'NOTA DE ENTREGA')
          }
        },
        {
          label: 'ORDEN DE TRASLADO',
          onClick: async () => {
            this.Mostrar(data,'ORDEN DE TRASLADO')
          }
        },
        {
          label: 'FACTURA',
          onClick: async () => {
            this.Mostrar(data,'FACTURA')
          }
        }
      ]
    });
  }
  Mostrar = async(data,tipo)=>{
    console.log(data, tipo)
    data.valores.formapago={
        totales : {
            ...data.valores.orden_venta['producto-subtotal']
        },
        'formapago-subtotal':{
            Tasa:data.valores.orden_venta['producto-subtotal'].Tasa,
            cancelar:data.valores.orden_venta['producto-subtotal'].total,
            total:data.valores.orden_venta['producto-subtotal'].total
        }
    }
    const cliente = await conexiones.Leer_C(['sistemachs_Cliente'],{
      sistemachs_Cliente:{_id:data.valores.orden_venta.cliente._id}
    })
    if (cliente.Respuesta==='Ok'){
      data.valores.orden_venta.cliente=cliente.datos.sistemachs_Cliente[0].valores;
    }
    this.setState({dialogo:{
        open:true,
        tam:'xl',
        fullScreen:true,
        Titulo: tipo,
        Cuerpo:
          <div style={{margin:5, height:window.innerHeight * 0.80}}>
            {tipo
              ? <Reporte datos={data} tipo={tipo}/>//<embed src={`${NotaEntrega(data)}#view=Fit&toolbar=1&navpanes=1&scrollbar=1`} type="application/pdf" width="100%" height={window.innerHeight * 0.80} />
              : null
            }
          </div>,
        Cerrar: this.Cerrar
    }})
  }
  Modificar = (data)=>{
    const {Config}=this.state;
    this.setState({dialogo:{
      open:true,
      tam:'xl',
      fullScreen:true,
      Titulo: `Orden de Traslado ${data.valores.recibo}`,
      Cuerpo:
        <div style={{margin:5, height:window.innerHeight * 0.885}}>
          <Venta Config={Config} Datos={data} Cerrar={this.Cerrar} Traslado/>
        </div>,
      Cerrar: this.Cerrar
    }})
  }
  
  Cerrar = () =>{
    
    setTimeout(async()=>{
      await this.state.props.Sincronizar();
      this.Refrescar();
    },3000);
    
    const {dialogo} = this.state;
    this.setState({dialogo:{...dialogo, open:false}})
  }
  
  Procesar = async(data) =>{
    await conexiones.Egreso_venta(data);
    this.Cerrar();
  }
  Traslado = () =>{
    const {Config}=this.state;
    this.setState({dialogo:{
        open:true,
        tam:'xl',
        fullScreen:true,
        Titulo: 'Nuevo Traslado',
        Cuerpo:
          <div style={{margin:5, height:window.innerHeight * 0.885}}>
            <Venta Config={Config} Cerrar={this.Cerrar} Traslado/>
          </div>,
        Cerrar: this.Cerrar
    }})
  }
 
  render(){
    const {cargando, datos, Config, titulos, dialogo}=this.state;
    const color =  Config.Estilos.Input_icono ? Config.Estilos.Input_icono : {};
    return (
      <div style={{width:'100%',height:'95%', position: "relative"}}>
        <Tabla
          
          Titulo={"Orden de Traslado"}
          Config={Config}
          titulos={titulos}
          table={''}
          cantidad={ null}
          datos={datos}
          Accion={this.Abrir}
          acciones={
            <Stack direction={'row'} justifyContent="center"
                    alignItems="center" sx={{p:1}}
            >
              <Box sx={{width:'20%'}}>
                <IconButton color={'primary'} title={'Crear nuevo traslado'} onClick={this.Traslado}>
                    <AddIcon style={color}/>
                </IconButton>
                <IconButton color={'primary'} title={'Refrescar valores'} onClick={this.Refrescar}>
                    <AutorenewIcon style={color}/>
                </IconButton>
              </Box>
              <Box sx={{width:'80%'}}>
                    <Formulario {...this.state.fecha} 
                        config={{...Ver_Valores().config,
                            Estilos:{
                                Input_label:{color:'#fff'}
                            }
                        }}
                    />
              </Box>
              
            </Stack>
          }
        />
        <Cargando open={cargando}/>
        <Dialogo  {...dialogo} config={Config}/>
       
      </div>
    )
  }
}
