import React, {Component} from 'react';
// import MailIcon from '@material-ui/icons/Mail';
// import NotificationsIcon from '@material-ui/icons/Notifications';
import Box from '@mui/material/Box';
import Stack from '@mui/material/Stack';
import {Titulos_todos ,conexiones, genera_formulario, Form_todos, Ver_Valores} from '../../../../constantes';
import Tabla from '../../../../componentes/herramientas/tabla';
import Dialogo from '../../../../componentes/herramientas/dialogo';
import Cargando from '../../../../componentes/esperar/cargar';
import Formulario from '../../../../componentes/herramientas/formulario';
import moment from 'moment';
import IconButton from '@mui/material/IconButton';
import AddIcon from '@mui/icons-material/AddCircle';
import AutorenewIcon from '@mui/icons-material/Autorenew';


export default class IngresoEgreso extends Component {
  constructor(props) {
      super(props);

      this.state = {
          cargando:true,
          props: this.props,
          Config:this.props.Config,
          datos:[],
          dialogo:{open:false},
          dialogo1:{open:false},
      }
  }

  Seleccion = (item)=>(dato) =>{

    // console.log(dato.target.innerText, dato.target.cellIndex, this.state.Titulos[dato.target.cellIndex].field)
    this.Abrir1(this.state.Titulos[item].field);
  }
  Seleccionar_dia = (dian)=>(value) =>{
    let dia = this.state.dia;
    let diaf = this.state.diaf;
    if (dian==='dia') dia = value['$d'];
    else diaf= value['$d']; 
    this.setState({[dian]:value['$d']});
    this.Inicio(dia, diaf)
  }
  Refrescar = ()=>{
    let dia = this.state.dia;
    let diaf = this.state.diaf;
    this.Inicio(dia, diaf);
  }
  Inicio = async(dia, diaf)=>{
    const {props} =  this.state;
    const {Egresar}= props;
    if (dia===undefined || dia===null){
      dia = new Date();
      dia.setDate(1);  
    }
    if (diaf===undefined || diaf===null){
      diaf = new Date();
      var ultimoDia = new Date(diaf.getFullYear(), diaf.getMonth() + 1, 0).getUTCDate();
      
      diaf.setDate(ultimoDia); 
    }
    this.setState({cargando:true});
    let forma = {...Form_todos('Form_fecha')};
    forma.columna= 2;
    let otro = {...forma.value[0], key:'fechaf', name:'fechaf', nombre:'fechaf'};
    forma.value=[...forma.value, otro];
    
    let nuevos = await genera_formulario({valores:{}, campos: forma });
    
    nuevos.titulos[0].value.fecha.value= dia;
    nuevos.titulos[0].value.fecha.label='Fecha Inicial';
    nuevos.titulos[0].value.fecha.onAccept = this.Seleccionar_dia('dia');
    nuevos.titulos[0].value.fechaf.value= diaf;
    nuevos.titulos[0].value.fechaf.label='Fecha Final';
    let titulos = await Titulos_todos('Titulos_Ingresos_Egresos');
    let resp= await conexiones.Leer_C([props.table],{
      [props.table]:{
        $and:[{"valores.tipo":Egresar ? "Egreso": "Ingreso"},
          {"valores.fecha":{$gte:moment(dia).format('YYYY-MM-DD'),$lte:moment(diaf).format('YYYY-MM-DD')}}
        ]
      }
      // {$and:[{"valores.fecha":{$gte:datos.fecha.dia,$lte:datos.fecha.diaf}}]}
    });
    let datos= [];
    if (resp.Respuesta==='Ok'){
        datos= resp.datos[props.table].sort((a,b)=> a.valores.codigo > b.valores.codigo ? -1 : 1);    
    }
    
    this.setState({cargando:false,  dia, diaf, fecha:nuevos, datos, titulos})
  }
  async componentDidMount(){
    this.Inicio();
    this.state.props.socket.on(`Actualizar`, data => {
      this.Inicio();     
    })
  }
  componentWillUnmount(){
    this.state.props.socket.off('Actualizar');
  }

  static getDerivedStateFromProps(props, state) {

    if (props !== state.props) {
        
      return {
        props,
        Config:props.Config,
      };
    }
    // No state update necessary
    return null;
  }

  Guardar = async(data)=>{
    const {table, id, Egresar}= this.state.props;
    data.fecha= moment(data.fecha ? data.fecha : new Date()).format('YYYY-MM-DD');
    data.tipo = Egresar ? 'Egreso' : 'Ingreso';
    data.moneda = data.moneda ? data.moneda.signo ? data.moneda.signo : data.moneda : "$";
    console.log(data)
    await conexiones.Guardar({valores:data, multiples_valores:true},table);
    
    // console.log(resp)
    this.Cerrar();
    let dia = this.state.dia;
    let diaf = this.state.diaf;
    this.Inicio(dia,diaf);
    // this.Abrir(resp.nuevo ? resp.nuevo : {_id: resp.datos._id, valores: resp.datos});
    return
  }
  Eliminar = async(data)=>{
    const {table}= this.state.props;
    await conexiones.Eliminar(data,[table]);
    this.Cerrar();
    // this.Abrir(resp.nuevo ? resp.nuevo : {_id: resp.datos._id, valores: resp.datos});
  }
  Agregar = ()=>{
    this.Abrir({valores:{}})
  }

    
  Abrir = async(data)=>{
    const {props}=this.state;
    const {Config}=this.state;
    const {Egresar, table, id} = props;
    
    if(data.valores && !data.valores.codigo){
        let resp =  await conexiones.Serial({tabla:table, id:id,cantidad:6, condicion:{'valores.tipo': Egresar ? 'Egreso' : 'Ingreso'}});

        if (resp.Respuesta==='Ok'){
            data.valores.codigo= resp.Recibo;
        }
    }
    const lista = Ver_Valores().config.Listas.lista_moneda;
    console.log(lista, data.valores);
    const moneda = data.valores.moneda ? lista[lista.findIndex(f=> f.signo===data.valores.moneda)] : lista[0];
    let nuevos = await genera_formulario({valores:{_id:data._id, ...data.valores, moneda }, campos: Form_todos('Form_Ingresos_Egresos') });
    
    
    nuevos.botones=[
        {
            name:'ingresar', label:Egresar ? 'Egresar' : 'Ingresar', title: Egresar ? 'Egresar datos al sistema' : 'Ingresar datos al sistema',
            variant:"contained", color:"success", 
            onClick: this.Guardar, validar:'true', 
            disabled: data.valores.dependiente,
            sx:{...Config.Estilos.Botones ? Config.Estilos.Botones.Aceptar : {}},
        },
        ...data._id!==undefined ? 
        [{
          name:'eliminar', label:'Eliminar', title: 'Eliminar dato del sistema',
          variant:"contained", color:"success", 
          onClick: this.Eliminar, validar:'true',
          // disabled: data.valores.dependiente, 
          sx:{...Config.Estilos.Botones ? Config.Estilos.Botones.Eliminar : {}},
          confirmar:'true', confirmar_mensaje:'Desea eliminar',confirmar_campo:'codigo',
        }] : []
    ]
    this.setState({dialogo:{
        open:true,
        
        Titulo: data._id ? `${data.valores.codigo}${data.valores.ref_movimiento ? ' - (POR PRODUCCIÓN DE '+ data.valores.ref_movimiento +')' : ''}` : Egresar ? 'Nuevo Egreso' : 'Nuevo Ingreso',
        Cuerpo:
          <div style={{margin:5,}}>
            <Formulario {...nuevos}/> 
          </div>,
        Cerrar: this.Cerrar
    }})
  }

  Cerrar = () =>{
    const {dialogo, dia, diaf} = this.state;
    this.Inicio(dia, diaf);
    this.setState({dialogo:{...dialogo, open:false}})
  }
  
  
  render(){
    const {cargando, datos, Config, titulos, dialogo}=this.state;
    const color =  Config.Estilos.Input_icono ? Config.Estilos.Input_icono : {};
    return (
      <div style={{width:'100%',height:'99%', position: "relative"}}>
        {datos===null
          ? null
          :
          <Tabla
            
            Titulo={this.state.props.Titulo ? this.state.props.Titulo : 'Titulo'}
            Config={Config}
            titulos={titulos}
            table={''}
            cantidad={ null}
            datos={datos}
            Accion={this.Abrir}
            acciones={
              <Stack direction={'row'} justifyContent="center"
                alignItems="center" sx={{p:1}}
              >
                <Box sx={{width:'20%'}}>
                  <IconButton color={'primary'} title={'Refrescar datos'} onClick={this.Refrescar}>
                      <AutorenewIcon style={color}/>
                  </IconButton>
                  <IconButton color={'primary'} title={'Agregrar nuevo dato'} onClick={this.Agregar}>
                      <AddIcon style={color}/>
                  </IconButton> 
                </Box>
                <Box>
                    <Formulario {...this.state.fecha}
                      config={{...Ver_Valores().config,
                        Estilos:{
                            Input_label:{color:'#fff'}
                        }
                      }}
                    />
                </Box>
                  
              </Stack>
            }
          />
        }
        <Cargando open={cargando}/>
        <Dialogo  {...dialogo} config={Config}/>
       
      </div>
    )
  }
}
