import * as React from 'react';
import { styled } from '@mui/material/styles';
import Box from '@mui/material/Box';
import Paper from '@mui/material/Paper';
import Grid from '@mui/material/Grid2';
import { Form_todos, genera_formulario, conexiones } from '../../../../constantes';
import moment from 'moment';
import Cargando from '../../../../componentes/esperar/cargar';
import Formulario from '../../../../componentes/herramientas/formulario';
import { Typography } from '@mui/material';
import { BarChart } from '@mui/x-charts/BarChart';
import { axisClasses } from '@mui/x-charts/ChartsAxis';
import { PieChart } from '@mui/x-charts/PieChart';



function valueFormatter(value) {
  return `${Number(value).toFixed(2)}`;
}

const chartSetting = {
  yAxis: [
    {
      label: 'Monto',
    },
  ],
  width: window.innerWidth * 0.8,
  height: 300,
  sx: {
    [`.${axisClasses.left} .${axisClasses.label}`]: {
      transform: 'translate(-13px, 0)',
    },
  },
};

const Item = styled(Paper)(({ theme }) => ({
  backgroundColor: '#fff',
  ...theme.typography.body2,
  padding: theme.spacing(1),
  textAlign: 'center',
  color: theme.palette.text.secondary,
  ...theme.applyStyles('dark', {
    backgroundColor: '#1A2027',
  }),
}));

export default function ReporteMes(props) {
    const [state,setState]= React.useState({cargando:true})

    const Cambio = (nuevo)=>{
        setState({...state, ...nuevo})
    }
    
    const Seleccionar_dia = (dian)=>(value) =>{
        let dia = state.dia;
        let diaf = state.diaf;
        if (dian==='dia') dia = value['$d'];
        else diaf= value['$d']; 
        // this.setState({[dian]:value['$d']});
        Inicio(dia, diaf)
      }
    const Inicio = async(dia, diaf)=>{
        
        if (dia===undefined || dia===null){
          dia = new Date();
          dia.setDate(1);  
        }
        if (diaf===undefined || diaf===null){
          diaf = new Date();
          var ultimoDia = new Date(diaf.getFullYear(), diaf.getMonth() + 1, 0).getUTCDate();
          
          diaf.setDate(ultimoDia); 
        }
        Cambio({cargando:true});
        let forma = {...Form_todos('Form_fecha')};
        forma.columna= 2;
        let otro = {...forma.value[0], key:'fechaf', name:'fechaf', nombre:'fechaf'};
        forma.value=[...forma.value, otro];
        
        let nuevos = await genera_formulario({valores:{}, campos: forma });
        
        nuevos.titulos[0].value.fecha.value= dia;
        nuevos.titulos[0].value.fecha.label='Fecha Inicial';
        nuevos.titulos[0].value.fecha.onAccept = Seleccionar_dia('dia');
        nuevos.titulos[0].value.fechaf.value= diaf;
        nuevos.titulos[0].value.fechaf.label='Fecha Final';
        nuevos.titulos[0].value.fechaf.onAccept = Seleccionar_dia('diaf');
        
        let resp= await conexiones.Ventas({fecha:{dia:moment(dia).format('YYYY-MM-DD'),diaf:moment(diaf).format('YYYY-MM-DD')} });
        
        let datos=[];
        let facturado=0;
        let pendiente=0;
        let cancelado=0;
        let deproduccion=0;
    
        if (resp.Respuesta==='Ok'){
          datos= [...resp.ventas];
          facturado=resp.facturado;
          pendiente=resp.pendiente;
          cancelado=resp.total;
          deproduccion=resp.deproduccion;
        }
        resp= await conexiones.Leer_C(["sistemachs_IngresoEgreso"],{"sistemachs_IngresoEgreso":{$and:[{"valores.fecha":{$gte:dia,$lte:diaf}}]}});
        
        let detalles = [];
        let ingresoegreso = [];
        let totalI = 0;
        let totalIb = 0;
        let totalE = 0;
        let totalEb = 0;
        if (resp.Respuesta==="Ok"){
          
          const diacc = dia;
          detalles = resp.datos.sistemachs_IngresoEgreso.map(val=>val.valores);
          
          while (diacc<=diaf) {
            const fechas = detalles.filter(f=> f.fecha === moment(diacc).format("YYYY-MM-DD"));
            let ingreso = 0;
            let ingresob = 0;
            // let tingreso = 0;
            let egreso = 0;
            let egresob = 0;
            // let tegreso = 0;
            
            
            if (fechas.length!==0){
              fechas.map(val=>{
                if (val.tipo==='Ingreso'){
                  ingreso+=val.moneda==='$' ? Number(val.monto) :0;
                  ingresob+= val.moneda==='Bs' ? Number(val.montob ? val.montob : val.monto) : 0;
                  totalI+=val.moneda==='$' ? Number(val.monto) :0;
                  totalIb+= val.moneda==='Bs' ? Number(val.montob ? val.montob : val.monto) : 0;
                }else {
                  egreso+=val.moneda==='$' ? Number(val.monto) : 0;
                  egresob+=val.moneda==='Bs' ? Number(val.montob ? val.montob : val.monto): 0;
                  totalE+=val.moneda==='$' ? Number(val.monto) : 0;
                  totalEb+=val.moneda==='Bs' ? Number(val.montob ? val.montob : val.monto): 0;
                }
              })
            }
            ingresoegreso=[...ingresoegreso,{
              ingreso,
              ingresob,
              egreso,
              egresob,
              dia:moment(diacc).format("DD")
            }]
            diacc.setDate(diacc.getDate()+1);
          }
        }
        
        Cambio({cargando:false, dia, diaf, fecha:nuevos, datos, facturado, deproduccion,pendiente, cancelado, detalles:ingresoegreso, totalI, totalEb, totalE, totalIb})  
        
        
    }
    React.useEffect(()=>{
        Inicio()
        return ()=>{

        }
    },[])
  return (
    <Box sx={{ flexGrow: 1 }}>
      <Grid container spacing={2}>
        <Grid size={12}>
          <Item>
            {state.fecha
                ?   <Formulario {...state.fecha} />
                :   null
            }
          </Item>
        </Grid>
        <Grid size={6}>
          <Item sx={{height:216, alignContent:'center'}}>
            <Typography variant="h6" align={'right'} color={'#0069c6'}>
                Facturado: ${Number(state.facturado ? state.facturado : 0).toFixed(2)}
            </Typography>
            <Typography variant="h6" align={'right'} color={'#e6f405'}>
                Monto Produción: ${Number(state.deproduccion ? state.deproduccion : 0).toFixed(2)}
            </Typography>
            <Typography variant="h6" align={'right'} color={'#00c60f'}>
                Ganancia: ${Number(state.deproduccion ? Number(state.facturado) - Number(state.deproduccion) : 0).toFixed(2)}
            </Typography>
            <Typography variant="h6" align={'right'} color={'#c61500'}>
                Por Cobrar: ${Number(state.pendiente ? state.pendiente : 0).toFixed(2)}
            </Typography>
          </Item>
        </Grid>
        <Grid size={6}>
          <Item>
            {state.facturado && state.deproduccion && state.pendiente
              ? <PieChart
                  series={[
                    {
                      data: [
                        { id: 0, value: state.facturado, label: 'Facturado', color:"#0069c6" },
                        { id: 1, value: state.deproduccion, label: 'Producción', color:"#e6f405"},
                        { id: 2, value: state.facturado - state.deproduccion, label: 'Ganancia', color:"#00c60f" },
                        { id: 3, value: state.pendiente, label: 'Por Cobrar', color:"#c61500" },
                      ],
                      highlightScope: { fade: 'global', highlight: 'item' },
                      faded: { innerRadius: 30, additionalRadius: -30, color: 'gray' },
                    },
                  ]}
                  width={400}
                  height={200}
                />
              : null
            }
          </Item>
        </Grid>
        <Grid size={12}>
          <Item>
            {state.detalles
              ?
                <BarChart
                
                    dataset={state.detalles}
                    xAxis={[{ scaleType: 'band', dataKey: 'dia' }]}
                    series={[
                      { dataKey: 'ingreso', label: 'Ingreso ($)', valueFormatter },
                      { dataKey: 'egreso', label: 'Egreso ($)', valueFormatter },
                      { dataKey: 'ingresob', label: 'Ingreso (Bs)', valueFormatter },
                      { dataKey: 'egresob', label: 'Egreso (Bs)', valueFormatter },
                    ]}
                    {...chartSetting}
                />
                
              : null
            }
          </Item>
        </Grid>
        <Grid size={6}>
          <Item>
            {state.totalI && state.totalE
              ? <PieChart
                  series={[
                    {
                      data: [
                        { id: 0, value: state.totalI, label: 'Ingreso ($)', color:"#24c600" },
                        { id: 1, value: state.totalE, label: 'Egreso ($)', color:"#c61500"},
                      ],
                      highlightScope: { fade: 'global', highlight: 'item' },
                      faded: { innerRadius: 30, additionalRadius: -30, color: 'gray' },
                    },
                  ]}
                  width={400}
                  height={200}
                />
              : null
            }
          </Item>
        </Grid>
        <Grid size={6}>
          <Item>
            {state.totalIb && state.totalEb
              ? <PieChart
                  series={[
                    {
                      data: [
                        { id: 0, value: state.totalIb, label: 'Ingreso (Bs)', color:"#24c600" },
                        { id: 1, value: state.totalEb, label: 'Egreso (Bs)', color:"#c61500"},
                      ],
                      highlightScope: { fade: 'global', highlight: 'item' },
                      faded: { innerRadius: 30, additionalRadius: -30, color: 'gray' },
                    },
                  ]}
                  width={400}
                  height={200}
                />
              : null
            }
          </Item>
        </Grid>
        
      </Grid>
      {state.cargando ? <Cargando open={true}/> : null}
    </Box>
  );
}
