import * as React from 'react';
import Reporte from './reporte';
import { styled } from '@mui/material/styles';
import Box from '@mui/material/Box';
import Paper from '@mui/material/Paper';
import Cargando from '../../../componentes/esperar/cargar';
import Cuerpo from '../../../componentes/herramientas/cuerpo';

const Item = styled(Paper)(({ theme }) => ({
    backgroundColor: theme.palette.mode === 'dark' ? '#000' : '#fff',
    ...theme.typography.body2,
    padding: theme.spacing(1),
    textAlign: 'center',
    color: theme.palette.text.secondary,
    height:window.innerHeight * 0.6,
  //   maxWidth:window.innerWidth * 0.5
}));

const Reportes = (props) =>{
    const [state,setState] = React.useState({});

    const Cambio = (nuevo)=>{
        setState({...state, ...nuevo});
    }
    React.useEffect(()=>{
        let Bloques={
            'Materia Prima':   <Reporte {...props} Titulo={'Materia Prima'} TituloDetalle={'Movimientos en el Mes'} 
                                Actualizar={['Actualizar_wesi_chs_server_material','Actualizar_inventariomp']}
                            />,
            Empaques:   <Reporte {...props} Titulo={'Empaque'} TituloDetalle={'Movimientos en el Mes'}
                            Actualizar={['Actualizar_wesi_chs_server_empaque','Actualizar_empaque']}
                        />,
            'Producto Terminado':  <Reporte {...props} Titulo={'Producto Terminado'} TituloDetalle={'Movimientos en el Mes'}
                                    Actualizar={['Actualizar_produccion','Actualizar_inventariopt']}
                                />
        }
        Cambio({Bloques});
    },[])

    return !state.Bloques ? <Cargando open={true}/>
        :(  <Item sx={{...props.Config.Estilos.Dialogo_cuerpo, height:'100%'}} elevation={6}>
                <Box sx={(theme) => ({ flexGrow: 1, 
                    height:'100%',
                    width:'100%',
                    
                    overflow: 'hidden hidden',
                    '&::-webkit-scrollbar': { height: 10, width:10, WebkitAppearance: 'none' },
                    '&::-webkit-scrollbar-thumb': {
                        borderRadius: 8,
                        border: '2px solid',
                        borderColor: theme.palette.mode === 'dark' ? '' : '#E7EBF0',
                        backgroundColor: 'rgba(0 0 0 / 0.5)',
                    },
                })}
                >
                    <Cuerpo Bloques={state.Bloques} ancho={'110%'} anchot={'103'}/>
                </Box>
            </Item>
        )

}

export default Reportes